          return [text({ labels: m.overlay.labels.map((l, i) => `${i}. ${l.kind} "${l.text}" at ${l.x},${l.y}`), symbols: m.overlay.symbols.map((s2, i) => `${i}. ${s2.kind} at ${s2.x},${s2.y}`) })];
